// Test the FULL optimal flow for multi-product-line invoice with different VAT rates
// This simulates what the production run SHOULD have done
const BASE = "https://kkpqfuj-amager.tripletex.dev/v2";
const TOKEN = "eyJ0b2tlbklkIjoyMTQ3NjI4NDYxLCJ0b2tlbiI6IjU2NDRjNDljLWU0YzYtNGU2OC05MWU5LWU0MzBhMWRiYTMzYSJ9";
const AUTH = "Basic " + btoa("0:" + TOKEN);
const TODAY = "2026-03-21";

let callCount = 0;

async function api(method: string, path: string, body?: any) {
  callCount++;
  const url = `${BASE}${path}`;
  console.log(`\n[Call ${callCount}] ${method} ${url}`);
  const opts: RequestInit = {
    method,
    headers: { "Authorization": AUTH, "Content-Type": "application/json" },
  };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(url, opts);
  const text = await res.text();
  let json: any;
  try { json = JSON.parse(text); } catch { json = text; }
  console.log(`  → ${res.status}`, JSON.stringify(json).slice(0, 800));
  if (!res.ok) throw new Error(`${res.status}: ${JSON.stringify(json).slice(0, 500)}`);
  return json;
}

async function main() {
  // Use unique product numbers to avoid collision with earlier sandbox tests
  const PRODUCTS = [
    { name: "Analysis Report SB", number: 19796 },
    { name: "Maintenance SB", number: 12145 },
    { name: "System Development SB", number: 15995 },
  ];

  // Step 1: PARALLEL — batch create products + resolve customer + resolve VAT
  console.log("=== Step 1: Parallel batch (products + customer + VAT) ===");
  const [productRes, custRes, vatRes] = await Promise.all([
    api("POST", "/product/list", PRODUCTS),
    api("GET", "/customer?fields=id,name&count=1"), // just get first customer for sandbox test
    api("GET", `/ledger/vatType?typeOfVat=OUTGOING&vatDate=${TODAY}&fields=*`),
  ]);

  // Parse products
  const products = productRes.values || [];
  const prodMap: Record<number, number> = {};
  for (const p of products) {
    prodMap[Number(p.number)] = p.id;
    console.log(`  Product: number=${p.number}, id=${p.id}, name=${p.name}`);
  }

  const customerId = custRes.values?.[0]?.id;
  console.log(`  Customer: id=${customerId}`);

  // Parse VAT types (sandbox only has 0%)
  const vatTypes = vatRes.values || [];
  console.log(`  VAT types available: ${vatTypes.map((v: any) => `${v.percentage}% (id=${v.id}, code=${v.number})`).join(", ")}`);
  const vat0 = vatTypes.find((v: any) => v.percentage === 0);

  // Step 2: Create invoice with product references
  console.log("\n=== Step 2: POST /invoice with product references ===");
  const invoicePayload = {
    invoiceDate: TODAY,
    invoiceDueDate: "2026-04-20",
    customer: { id: customerId },
    orders: [{
      customer: { id: customerId },
      orderDate: TODAY,
      deliveryDate: TODAY,
      orderLines: [
        {
          description: "Analysis Report SB",
          count: 1,
          unitPriceExcludingVatCurrency: 27700,
          vatType: { id: vat0!.id },
          product: { id: prodMap[19796] },
        },
        {
          description: "Maintenance SB",
          count: 1,
          unitPriceExcludingVatCurrency: 12700,
          vatType: { id: vat0!.id },
          product: { id: prodMap[12145] },
        },
        {
          description: "System Development SB",
          count: 1,
          unitPriceExcludingVatCurrency: 7050,
          vatType: { id: vat0!.id },
          product: { id: prodMap[15995] },
        },
      ],
    }],
  });

  const invRes = await api("POST", "/invoice?sendToCustomer=false", invoicePayload);
  const invoiceId = invRes.value?.id;
  console.log(`\nInvoice created: id=${invoiceId}`);
  console.log(`  Amount excl VAT: ${invRes.value?.amountExcludingVatCurrency}`);
  console.log(`  Amount incl VAT: ${invRes.value?.amountCurrency}`);

  // Step 3: Readback to verify products are on order lines
  console.log("\n=== Step 3: Readback to verify products ===");
  const readback = await api("GET", `/invoice/${invoiceId}?fields=*,orders(*,orderLines(*,product(*),vatType(*)))`);
  const orderLines = readback.value?.orders?.[0]?.orderLines || [];
  console.log(`\nOrder lines on invoice:`);
  for (const ol of orderLines) {
    console.log(`  - desc="${ol.description}", product.number="${ol.product?.number}", product.name="${ol.product?.name}", amount=${ol.unitPriceExcludingVatCurrency}, vatType=${ol.vatType?.percentage}%`);
  }

  console.log(`\n=== TOTAL API CALLS: ${callCount} (3 parallel + 1 invoice + 1 readback) ===`);
  console.log(`Without readback: ${callCount - 1} calls (optimal for production)`);
}

main().catch(e => { console.error("FATAL:", e.message); process.exit(1); });

